export default async (ctx, client) => {
  const raw = await client.connections.list();
  const items = Array.isArray(raw) ? raw : (raw.items ?? raw.data ?? raw.connections ?? []);
  return {
    org: ctx.organization_id,
    shape: Array.isArray(raw) ? 'array' : Object.keys(raw),
    count: items.length,
    chat: items
      .filter(c => ['slack','telegram','discord','whatsapp'].includes(c.connector_key))
      .map(c => ({ id: c.id, key: c.connector_key, slug: c.slug, status: c.status, agent_id: c.agent_id, name: c.name })),
  };
}

