export default async (ctx, client) => {
  const tabId = 558570313;
  // Focus the search box via click, then type with the ref API (real keystrokes).
  const tree = await client.operations.execute({
    connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" },
  });
  const nodes = tree?.output?.tree ?? [];
  const epoch = tree?.output?.document_epoch;
  const search = nodes.find(n => n.id === 'telegram-search-input');
  if (!search) return { err: 'no search box', nodes: nodes.slice(0,5), epoch };
  await client.operations.execute({
    connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: search.ref_id, document_epoch: epoch } },
  });
  await ctx.sleep(1500);
  await client.operations.execute({
    connection_id: 432, operation_key: "type_ref",
    input: { tab_id: tabId, ref: { ref_id: search.ref_id, document_epoch: epoch }, text: "burembalobubot", clear_first: true },
  });
  await ctx.sleep(6000);
  const ev = await client.operations.execute({
    connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({
      val: document.querySelector('#telegram-search-input')?.value,
      results: [...document.querySelectorAll('a[href^="#"]')].slice(0,8).map(a=>({href:a.getAttribute('href'), txt:a.innerText.trim().slice(0,50)}))
    })` },
  });
  return ev;
}

