export default async (ctx, client) => {
  const tabId = 558570313;
  const tree = await client.operations.execute({
    connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" },
  });
  const nodes = tree?.output?.tree ?? [];
  const epoch = tree?.output?.document_epoch;
  const box = nodes.find(n => /message/i.test(n.name||'') && (n.role === 'textbox' || n.tag === 'div'))
           || nodes.find(n => n.role === 'textbox');
  if (!box) return { err: 'no composer', nodes: nodes.map(n=>({r:n.ref_id,n:n.name,role:n.role})).slice(-15) };
  await client.operations.execute({
    connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: epoch } },
  });
  await ctx.sleep(1200);
  await client.operations.execute({
    connection_id: 432, operation_key: "type_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: epoch },
             text: "e2e telegram check 2026-07-29: reply with a short hello and tell me which agent you are.", clear_first: true },
  });
  await ctx.sleep(2000);
  const before = await client.operations.execute({
    connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({typed: document.querySelector('[contenteditable="true"]')?.innerText?.slice(0,120)})` },
  });
  return { box: { ref: box.ref_id, name: box.name }, before };
}

