export default async (ctx, client) => {
  const tabId = 558570317;
  const tree = await client.operations.execute({
    connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" },
  });
  const nodes = tree?.output?.tree ?? [];
  const epoch = tree?.output?.document_epoch;
  const box = nodes.find(n => /^message$/i.test((n.name||'').trim()));
  if (!box) return { err: 'no composer', nodes: nodes.map(n=>({r:n.ref_id,n:n.name})).slice(-12) };
