export default async (ctx, client) => {
  try {
    const r = await client.conversations.list({
      action: "send",
      agent_id: "personal-agent",
      text: "reply with the single word: pong",
      wait: true,
      timeout_ms: 60000,
    });
    return { ok: true, r };
  } catch (e) { return { err: String(e.message) }; }
}

export default async (ctx, client) => {
  const out = { methods: Object.keys(client.conversations ?? {}) };
  try {
    out.send = await client.conversations.send({
      agent_id: "personal-agent",
      text: "reply with the single word: pong",
      wait: true,
      timeout_ms: 60000,
    });
  } catch (e) { out.sendErr = String(e.message); }
  return out;
}

