export default async (ctx, client) => {
  const nav = await client.operations.execute({
    connection_id: 432, operation_key: "navigate",
    input: { url: "https://web.telegram.org/a/#8834276769", open_in_new_tab: true, wait_for_load: true },
  });
  const tabId = nav?.output?.tab_id;
  await ctx.sleep(9000);
  const tree = await client.operations.execute({
    connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" } });
  const nodes = tree?.output?.tree ?? [];
  const epoch = tree?.output?.document_epoch;
  const box = nodes.find(n => /^message$/i.test((n.name||'').trim()));
  if (!box) return { err: 'no composer', tabId, nodes: nodes.map(n=>({r:n.ref_id,n:n.name})).slice(-10) };
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: epoch } } });
  await ctx.sleep(1200);
  await client.operations.execute({ connection_id: 432, operation_key: "type_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: epoch },
             text: "retest 0330 after rebuild: say hi", clear_first: true } });
  await ctx.sleep(2500);
  const t2 = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" } });
  const n2 = t2?.output?.tree ?? []; const e2 = t2?.output?.document_epoch;
  const send = n2.find(n => /send message|^send$/i.test((n.name||'').trim()));
  if (!send) return { err: 'no send', tabId };
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: send.ref_id, document_epoch: e2 } } });
  await ctx.sleep(20000);
  const ev = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({ tail: document.body.innerText.slice(-400) })` } });
  return { tabId, ev };
}

