export default async (ctx, client) => {
  const tabId = 558570336;
  // Clear the stale draft, type fresh, and submit with a real Enter keypress.
  await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `(() => {
      const el = document.querySelector('#editable-message-text') || document.querySelector('[contenteditable="true"]');
      if (!el) return 'no-composer';
      el.focus();
      document.execCommand('selectAll', false, null);
      document.execCommand('delete', false, null);
      return 'cleared:' + (el.innerText||'').length;
    })()` } });
  await ctx.sleep(1500);
  const tree = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" } });
  const nodes = tree?.output?.tree ?? []; const epoch = tree?.output?.document_epoch;
  const box = nodes.find(n => /^message$/i.test((n.name||'').trim()));
  if (!box) return { err: 'no composer ref' };
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: epoch } } });
  await ctx.sleep(1000);
  await client.operations.execute({ connection_id: 432, operation_key: "type_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: epoch },
             text: "QQTRACE55 hello lobu", clear_first: true } });
  await ctx.sleep(2000);
  // Submit via Enter keydown/keypress/keyup on the composer.
  await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `(() => {
      const el = document.querySelector('#editable-message-text') || document.querySelector('[contenteditable="true"]');
      if (!el) return 'no-composer';
      el.focus();
      for (const type of ['keydown','keypress','keyup']) {
        el.dispatchEvent(new KeyboardEvent(type, {key:'Enter', code:'Enter', keyCode:13, which:13, bubbles:true, cancelable:true}));
      }
      return 'enter-sent; draft=' + JSON.stringify((el.innerText||'').slice(0,40));
    })()` } });
  await ctx.sleep(6000);
  const after = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `(() => {
      const items = [...document.querySelectorAll('.message-list-item')].slice(-5).map(m=>m.innerText.trim().replace(/\\n/g,' ').slice(0,70));
      const draft = (document.querySelector('#editable-message-text')||{}).innerText || '';
      return JSON.stringify({ items, draft: draft.slice(0,50) });
    })()` } });
  return after;
}

