export default async (ctx, client) => {
  const tabId = 558570341;
  const t = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" } });
  const nodes = t?.output?.tree ?? []; const epoch = t?.output?.document_epoch;
  // Match by geometry: the send button sits at x~1428 y~825.
  const send = nodes.find(n => n.bbox && Math.abs(n.bbox.x + n.bbox.w/2 - 1428) < 30 && Math.abs(n.bbox.y + n.bbox.h/2 - 825) < 30)
            || nodes.find(n => /send/i.test(n.name||''));
  if (!send) return { err:'no send node', epoch, tail: nodes.slice(-12).map(n=>({r:n.ref_id,n:n.name,b:n.bbox})) };
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: send.ref_id, document_epoch: epoch } } });
  await ctx.sleep(6000);
  const ev = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({
      items: [...document.querySelectorAll('.message-list-item')].map(m=>m.innerText.trim().replace(/\\n/g,' ').slice(0,60)),
      draft: document.querySelector('#editable-message-text')?.innerText?.slice(0,30)
    })` } });
  return { clicked: { ref: send.ref_id, name: send.name, bbox: send.bbox }, ev };
}

