export default async (ctx, client) => {
  const tabId = 558570341;
  // Hard-clear the composer first (execCommand works for editing; only SEND needs trust).
  await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `(() => {
      const el = document.querySelector('#editable-message-text');
      el.focus(); document.execCommand('selectAll', false, null); document.execCommand('delete', false, null);
      return 'len=' + (el.innerText||'').trim().length;
    })()` } });
  await ctx.sleep(1000);
  const t1 = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" } });
  const n1 = t1?.output?.tree ?? []; const e1 = t1?.output?.document_epoch;
  const box = n1.find(n => /^message$/i.test((n.name||'').trim()));
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: e1 } } });
  await ctx.sleep(800);
  await client.operations.execute({ connection_id: 432, operation_key: "type_ref",
    input: { tab_id: tabId, ref: { ref_id: box.ref_id, document_epoch: e1 }, text: "KK4477 ping", clear_first: false } });
  await ctx.sleep(2500);
  const t2 = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "interactive" } });
  const n2 = t2?.output?.tree ?? []; const e2 = t2?.output?.document_epoch;
  const send = n2.find(n => /send message/i.test(n.name||''));
  const before = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({draft: document.querySelector('#editable-message-text')?.innerText})` } });
  if (!send) return { err:'no send', before };
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: send.ref_id, document_epoch: e2 } } });
  await ctx.sleep(9000);
  const after = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({
      items: [...document.querySelectorAll('.message-list-item')].map(m=>m.innerText.trim().replace(/\\n/g,' ').slice(0,50)),
      draft: document.querySelector('#editable-message-text')?.innerText
    })` } });
  return { before, after, sendRef: send.ref_id, bbox: send.bbox };
}

