export default async (ctx, client) => {
  const tabId = 558570341;
  // Focus the tab so CDP input lands, then click the send button by coordinate
  // using a synthetic-but-CDP-dispatched click via the a11y tree's nearest node.
  await client.operations.execute({ connection_id: 432, operation_key: "focus_tab", input: { tab_id: tabId } });
  await ctx.sleep(1500);
  const t = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree",
    input: { tab_id: tabId, filter: "all" } });
  const nodes = t?.output?.tree ?? []; const epoch = t?.output?.document_epoch;
  const hit = nodes.filter(n => n.bbox && n.bbox.w>0 &&
      Math.abs(n.bbox.x + n.bbox.w/2 - 1428) < 26 && Math.abs(n.bbox.y + n.bbox.h/2 - 825) < 26)
    .map(n => ({ r:n.ref_id, name:n.name, tag:n.tag, role:n.role, b:n.bbox }));
  return { epoch, count: nodes.length, hit };
}

