/**
 * Inbound dispatch must behave identically for every chat adapter.
 *
 * Chat SDK runs `messageHistory.append()` inside `handleIncomingMessage`
 * BEFORE `dispatchToHandlers`, guarded only by the adapter's
 * `persistMessageHistory` flag. Telegram and WhatsApp set that flag; Slack,
 * Discord, Teams and GChat do not. The append is unguarded, so any throw
 * inside it is caught by `processMessage`'s catch-all, logged at `debug`, and
 * the inbound message is silently discarded — the webhook still returns 200.
 *
 * That made a durable-history *cache* write able to drop a user's message, and
 * only on the two platforms that set the flag (prod: a Telegram DM returned 200
 * with no reply and no error, while Slack on the same build was unaffected).
 *
 * Lobu already persists transcripts itself via `captureChannelMessage` →
 * `channel_messages`, which is platform-agnostic, idempotent and explicitly
 * fire-and-forget. The SDK cache has zero readers in this repo, so history
 * persistence must never be able to block dispatch.
 *
 * These tests pin the invariant: a failing history store still dispatches, for
 * every adapter, regardless of `persistMessageHistory`.
 */
import { describe, expect, test } from "bun:test";
import { Chat } from "chat";

/** In-memory StateAdapter whose list ops fail, standing in for any store fault. */
function createStateAdapter(options: { failListAppend: boolean }) {
	const kv = new Map<string, unknown>();
	const locks = new Set<string>();
	const subs = new Set<string>();
	const lists = new Map<string, unknown[]>();
	return {
		async connect() {},
		async disconnect() {},
		async get(key: string) {
			return kv.get(key) ?? null;
		},
		async set(key: string, value: unknown) {
			kv.set(key, value);
		},
		async setIfNotExists(key: string, value: unknown) {
			if (kv.has(key)) return false;
			kv.set(key, value);
			return true;
		},
		async delete(key: string) {
			kv.delete(key);
		},
		async acquireLock(threadId: string) {
			if (locks.has(threadId)) return null;
			locks.add(threadId);
			return { threadId, token: "t", expiresAt: Date.now() + 60_000 };
		},
		async releaseLock(lock: { threadId: string }) {
			locks.delete(lock.threadId);
		},
		async forceReleaseLock(threadId: string) {
			locks.delete(threadId);
		},
		async isSubscribed(threadId: string) {
			return subs.has(threadId);
		},
		async subscribe(threadId: string) {
			subs.add(threadId);
		},
		async unsubscribe(threadId: string) {
			subs.delete(threadId);
		},
		async appendToList(key: string, value: unknown) {
			if (options.failListAppend) {
				throw new Error("history store unavailable");
			}
			const existing = lists.get(key) ?? [];
			existing.push(value);
			lists.set(key, existing);
		},
		async getList(key: string) {
			return lists.get(key) ?? [];
		},
		async trimList() {},
		async queuePush() {},
		async queuePop() {
			return null;
		},
		async queueSize() {
			return 0;
		},
	};
}

/**
 * Minimal adapter implementing the surface `handleIncomingMessage` touches.
 * `persistMessageHistory` is the only axis under test.
 */
function createAdapter(persistMessageHistory: boolean) {
	return {
		name: "test",
		userName: "lobubot",
		botUserId: "999",
		persistMessageHistory,
		isDM: (threadId: string) => !threadId.includes(":group"),
		channelIdFromThreadId: (threadId: string) => threadId,
		getChannelVisibility: () => "private" as const,
		async postMessage() {
			return {} as Record<string, unknown>;
		},
		parseMessage: (raw: unknown) => raw,
	};
}

function createMessage(text: string) {
	return {
		id: "m1",
		text,
		author: {
			userId: "42",
			userName: "human",
			fullName: "Human",
			isBot: false,
			isMe: false,
		},
		isMention: false,
		metadata: {},
		toJSON: () => ({ id: "m1", text, raw: null }),
	};
}

/**
 * Drive one inbound DM through the real Chat SDK and report whether the
 * registered handler ran.
 */
async function dispatchOnce(params: {
	persistMessageHistory: boolean;
	failListAppend: boolean;
}): Promise<string[]> {
	const delivered: string[] = [];
	const adapter = createAdapter(params.persistMessageHistory);
	const chat = new Chat({
		userName: "lobubot",
		adapters: { test: adapter as never },
		state: createStateAdapter({
			failListAppend: params.failListAppend,
		}) as never,
		logger: "silent",
	});
	chat.onDirectMessage(async (_thread: unknown, message: { text: string }) => {
		delivered.push(message.text);
	});
	await chat.initialize();
	// Await the SDK's internal task: processMessage swallows errors, so the
	// assertion is on `delivered`, never on this call throwing.
	await (
		chat as unknown as {
			handleIncomingMessage: (
				a: unknown,
				t: string,
				m: unknown,
			) => Promise<void>;
		}
	).handleIncomingMessage(adapter, "test:dm-1", createMessage("hello"));
	return delivered;
}

describe("inbound dispatch parity across chat adapters", () => {
	test("dispatches when the history store is healthy (persistMessageHistory=true)", async () => {
		expect(
			await dispatchOnce({
				persistMessageHistory: true,
				failListAppend: false,
			}),
		).toEqual(["hello"]);
	});

	test("dispatches for adapters that do not persist history", async () => {
		expect(
			await dispatchOnce({
				persistMessageHistory: false,
				failListAppend: false,
			}),
		).toEqual(["hello"]);
	});

	// The regression. Slack/Discord/Teams/GChat pass this trivially because they
	// never execute the append; Telegram/WhatsApp dropped the message entirely.
	test("a failing history store must NOT drop the message", async () => {
		expect(
			await dispatchOnce({ persistMessageHistory: true, failListAppend: true }),
		).toEqual(["hello"]);
	});

	// Parity: the persistMessageHistory flag must not change delivery at all.
	test("delivery is identical whether or not the adapter persists history", async () => {
		const persisting = await dispatchOnce({
			persistMessageHistory: true,
			failListAppend: true,
		});
		const nonPersisting = await dispatchOnce({
			persistMessageHistory: false,
			failListAppend: true,
		});
		expect(persisting).toEqual(nonPersisting);
	});
});

