const logger = createLogger("chat-instance-manager");

/**
 * Log level handed to the Chat SDK.
 *
 * This used to be hardcoded `"warn"`, which made the SDK's internal
 * inbound-drop paths unreachable in production: every early return in
 * `handleIncomingMessage` (self-authored, duplicate, lock conflict) and the
 * catch-all in `processMessage` log at `debug`, so a swallowed exception left
 * no trace at any `LOG_LEVEL`. Honour `LOG_LEVEL` so `LOG_LEVEL=debug` can
 * actually surface them, while defaulting to the previous `"warn"` (the SDK is
 * chatty at `info`).
 */
function sdkLogLevel(): "debug" | "info" | "warn" | "error" | "silent" {
  const level = process.env.LOG_LEVEL?.toLowerCase();
  return level === "debug" || level === "trace" ? "debug" : "warn";
}

