/**
 * Turn off the Chat SDK's message-history cache so every adapter shares one
 * inbound path.
 *
 * The SDK writes that cache in `handleIncomingMessage` BEFORE dispatch, gated
 * on the adapter's `persistMessageHistory` flag and unguarded; `processMessage`
 * swallows the throw and still answers 200, so a failing *cache* write silently
 * drops the message. Only Telegram and WhatsApp set the flag, so one build
 * dropped Telegram DMs while Slack was fine. Nothing reads the cache — Lobu's
 * own transcripts go to `channel_messages` via `captureChannelMessage` — so
 * this deletes a write, it does not replace one.
 */
export function disableSdkMessageHistory<T>(adapter: T): T {
  // Declared readonly on the SDK interface, so redefine rather than assign.
  Object.defineProperty(adapter as object, "persistMessageHistory", {
    value: false,
    configurable: true,
    writable: true,
  });
  return adapter;
}

