  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: tabId, ref: { ref_id: send.ref_id, document_epoch: e2 } } });
  await ctx.sleep(5000);
  const ev = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({ items: [...document.querySelectorAll('.message-list-item')].map(m=>m.innerText.trim().replace(/\\s+/g,' ').slice(0,45)), draft: document.querySelector('#editable-message-text')?.innerText })` } });
  return { tabId, result: ev?.output?.value };
}

