export default async (ctx, client) => {
  const nav = await client.operations.execute({
    connection_id: 432, operation_key: "navigate",
    input: { url: "https://web.telegram.org/a/#8834276769", open_in_new_tab: true, wait_for_load: true },
  });
  const tabId = nav?.output?.tab_id;
  await ctx.sleep(9000);
  const ev = await client.operations.execute({
    connection_id: 432, operation_key: "evaluate",
    input: { tab_id: tabId, expression: `JSON.stringify({
      items: [...document.querySelectorAll('.message-list-item')].map(m=>m.innerText.trim().replace(/\\s+/g,' ').slice(0,90))
    })` },
  });
  return { tabId, result: ev?.output?.value };
}
